f="<?=url('admin/rooms/index.php')?>">Manage room inventory</a><?php else: ?><a class="btn btn-primary" href="<?=url('staff/index.php')?>">Return to reception overview</a><?php endif; ?></div><?php endif; ?></div></div></section><?php include '../includes/footer.php';?>